/**
 * Put the sprite in the document. Safe to call more than once.
 * @param {Document} root
 */
export function installFileIcons(root) {
  if (root.getElementById('fi-file')) return;
  root.body.insertAdjacentHTML('afterbegin', SPRITE);
}

/**
 * The icon a file gets: its whole name first, then its suffixes from the
 * longest — `foo.d.ts` before `ts` — then the page.
 *
 * Case-sensitive, because Zed's is: the set's names are written in lower
 * case, so `README.md` gets the Markdown mark rather than the readme one, and
 * that is what the same tree shows in Zed.
 * @param {string} name
 * @returns {string}
 */
export function fileIconName(name) {
  if (NAMES[name]) return NAMES[name];
  for (let at = name.indexOf('.'); at !== -1; at = name.indexOf('.', at + 1)) {
    const icon = SUFFIXES[name.slice(at + 1)];
    if (icon) return icon;
  }
  return 'file';
}

/** @param {string} id */
const use = (id) => `<svg class="fi" aria-hidden="true"><use href="#fi-${id}"/></svg>`;

/** @param {string} name */
export const fileIconHtml = (name) => use(fileIconName(name));

/** @param {boolean} open */
export const folderIconHtml = (open) => use(open ? 'folder-open' : 'folder');
